# November 15, 2026: Rhode Island first pass. Facts from the linked sources only (Wikipedia articles read in full,
# plus the National Park Service and RI state parks pages where linked).
# Where sources disagree or say nothing, the text says "not confirmed" and conf is set.
# Each pin was looked at once on the March 2026 RIGIS leaf-off aerial (test/ri_pins_*.jpg); no pin was moved.
# Each pin note says where the coordinate came from and, where it matters, what the aerial showed.
from data_b import N
from data_ma import W,WK
GEOP='Pin is from an ArcGIS address lookup; not checked against imagery.'
R=[
# ---- Narragansett Bay and Newport ----
N('rocky-point-park','Rocky Point amusement park','Warwick','ribay','amuse','traces',41.68917,-71.3675,'site','public','walk','amusements','1847–1995',
  'An amusement park on Narragansett Bay that began in 1847, when William Winslow started serving dinners and offering amusements. It closed in the mid-1990s and its owners filed for bankruptcy in 1996. Fires hit the empty buildings in 2004 and 2006, the midway came down from May 2007 and the last buildings went in 2014. The closing year is not confirmed: the articles give both 1995 and November 1994.',
  'The 1906 Circle Swing tower, the upper and lower stations and support towers of the Skyliner gondola, the ruin of an old water tank, and the big arch by the entrance. The arch came from the 1964 World\'s Fair in New York and was moved here in 1966.',
  'An amusement park that became a state park, with the gondola stations still standing.',
  'Rocky Point State Park, opened October 25, 2014. The last of the land passed to the state in March 2013.',[W('Rocky Point Amusement Park'),W('Rocky Point State Park')]),
N('fort-wetherill','Fort Wetherill','Jamestown','ribay','fort','ruins',41.47733,-71.35783,'site','public','walk','forts','1899–1946',
  'A coast artillery fort on the granite cliffs at the east tip of Conanicut Island. The government bought the land in 1899 and built over the older Fort Dumpling. Most of the big guns were scrapped by 1943 and the military left in 1946. The site sat empty until the state took it on August 16, 1972.',
  'Concrete gun batteries, most of them buried up to the loading platforms and covered in graffiti. The mine storehouse is restored, with plaques and the remains of its tram tracks.',
  '','Fort Wetherill State Park, run by DEM, with parking and trails. Parts of the fort have been fenced off because of decay. Stay outside the fences.',[W('Fort Wetherill')]),
N('the-bells-brenton-point','The Bells at Brenton Point','Newport','ribay','landmark','ruins',41.44861,-71.355,'area','public','walk','burned','1876–1963',
  'Theodore M. Davis built the mansion called The Reef between 1876 and 1883. After the wooden stables burned in 1906 he put up a stone carriage house and a stone lookout tower, together called The Bells. The empty mansion was damaged by fire in 1960 or 1961 and torn down in 1963.',
  'The stone tower still stands. The carriage house does not: it was demolished in February 2024 after trespassing teenagers fell through its roof. Many older write-ups still describe it as standing. One round concrete gun mount from the World War II battery is also here.',
  'The famous ruin is gone; the tower is what is left.',
  'Brenton Point State Park, run by DEM.',[W('Brenton Point State Park')]),
N('dutch-island-fort-greble','Fort Greble, Dutch Island','Jamestown','ribay','fort','ruins',41.50389,-71.4,'area','view','boat','forts','1897–1947',
  'Dutch Island was fortified from the Civil War on and was called Fort Greble from 1898. Its first modern battery was finished in 1897. The fort went into caretaker status, its guns were scrapped in 1942, it held German prisoners in World War II and it was given up in 1947.',
  'A lighthouse and military buildings remain on the island. Look from the water or from the shore.',
  '','Not open to the public. The state owns the island and DEM manages it as a wildlife area. Do not land.',[W('Dutch Island (Rhode Island)')]),
N('conanicut-battery','Conanicut Battery','Jamestown','ribay','fort','traces',41.48028,-71.39389,'site','public','walk','forts','1776',
  'Local militia built an earth battery here in the Revolution. The British took it over and held it until the French fleet came in August 1778. In the early 1900s the Army built large, partly underground batteries nearby, at Fort Getty and Fort Burnside.',
  'An earthwork about 150 feet long and 75 feet wide, with a 1931 plaque. The site looks over the West Passage.',
  '','Owned by the town. Hours and parking were not checked.',[W('Conanicut Battery')]),
N('fort-burnside-beavertail','Fort Burnside at Beavertail','Jamestown','ribay','fort','standing',41.44889,-71.39944,'area','public','walk','forts','1942–1948',
  'Fort Burnside was set up in 1942 at the south end of Conanicut Island, with a 6-inch and a 3-inch battery in place by late 1943. Its guns were scrapped in 1948. The first lighthouse here was a wooden tower of 1749 that burned in 1753; the present tower dates from 1856.',
  'The harbor entrance control post, built to look like a seaside mansion, still exists. Where it stands in the park was not located. The lighthouse museum is in the 1898 assistant keeper\'s house.',
  'A wartime command post disguised as a summer house.',
  'Beavertail State Park.',[W('Beavertail State Park')]),
N('fort-hamilton-rose-island','Fort Hamilton, Rose Island','Newport','ribay','fort','ruins',41.49547,-71.34272,'area','boat','boat','forts','1798–1801',
  'A First System coastal fort begun in 1798 and never finished. It was later an ammunition depot in both World Wars. It is one of the last forts of its generation left in the country.',
  'Original bombproof barracks, bastions and curtain walls. The lighthouse of 1870 stands on one of the bastions.',
  '','On an island reached only by boat. The Rose Island Lighthouse and Fort Hamilton Trust looks after it and opens it to visitors; check with the trust for boats and hours.',[W('Fort Hamilton (Rhode Island)'),W('Rose Island Light')]),
N('fort-barton','Fort Barton','Tiverton','ribay','fort','traces',41.6253,-71.207,'site','public','walk','forts','1777',
  'A Revolutionary War fort built in 1777 above the main ferry crossing to Aquidneck Island, which the British then held. American troops crossed from here for the Battle of Rhode Island in August 1778.',
  'Only the earthworks are left, roughly 150 feet long and 100 feet deep.',
  '','Public park at Lawton and Highland avenues.',[W('Fort Barton Site')]),
N('newport-tower','Newport Tower (Old Stone Mill)','Newport','ribay','landmark','standing',41.4858,-71.3099,'exact','public','drive','','1600s',
  'A round stone tower about 28 feet tall, most likely the shell of a windmill from the mid-1600s. Governor Benedict Arnold mentioned his stone-built windmill in his will in 1677, and carbon dating of the mortar gives a 1600s date.',
  'The round stone tower in Touro Park.','','City park.',[W('Newport Tower (Rhode Island)')]),
# ---- Providence, the Blackstone Valley and the west ----
N('crook-point-bridge','Crook Point Bascule Bridge','Providence','riprov','rail','standing',41.82379,-71.38497,'exact','view','drive','','1908–1976',
  'A railroad lift bridge over the Seekonk River, built in 1908 as part of the East Side tunnel project and abandoned in 1976. It was fixed in the raised position to let boats through and has stayed that way. Locals call it the Stuck-Up Bridge.',
  'The rusted span standing upright over the river. See it from the shore.',
  'The bridge that has been stuck open for fifty years.',
  'Not open: do not go onto the bridge or its approaches. In 2018 RIDOT said it planned to demolish it in 2026–2027, and in January 2025 Providence moved to take it over from RIDOT to stop that. Its present state was not confirmed, so check that it is still there.',[W('Crook Point Bascule Bridge')]),
N('east-side-rail-tunnel','East Side Railroad Tunnel','Providence','riprov','rail','standing',41.82519,-71.39029,'area','view','drive','','1908–1976',
  'A railroad tunnel 5,080 feet long under College Hill, opened on November 16, 1908 and abandoned in 1976. Its east portal is on the east side of Gano Street and its west portal is between North Main and Benefit streets.',
  'The east portal at Gano Street. The pin marks a street corner on Gano Street, not the portal.',
  '','Owned by RIDOT. Both portals were blocked with corrugated steel. Sealed tunnel: look from the street only.',[W('East Side Railroad Tunnel')]),
N('hanton-city','Hanton City','Smithfield','riprov','town','ruins',41.92285,-71.52137,'area','ask','hike','','colonial–c.1900',
  'A colonial-era settlement known locally as Lost City, cut off from the main town of Smithfield. A local historian suggests three families, the Paines, Hantons and Shippees, may have been granted the land after King Philip\'s War. The last Hanton living there is said to have died around 1900.',
  'Stone foundations and cellar holes, a burial ground, an old dam, wells and stone walls, spread out along a former cart road. It is overgrown and hard to find in leaf. The pin marks Hanton City Trail, the road, not the ruins; hunt on LiDAR.',
  'A village that faded out and left its cellar holes in the woods.',
  'Access not confirmed. Ownership is a mix of private land, Audubon Society and Smithfield Land Trust land, and public land. One source says Hanton City Trail gives access; another says the land trust parcel has no public access. Ask the land trust before going.',
  [W('Hanton City, Rhode Island'),['New England Diary','https://www.newenglanddiary.com/blog/2026-5-22-kuc35udfwftiasggqad2wakhncrd6x'],['Auntie Beak: Hanton City','https://auntiebeak.com/hanton-city']],conf='mixed'),
N('blackstone-canal-lincoln','Blackstone Canal at the Kelly House','Lincoln','riprov','canal','traces',41.93404,-71.43216,'site','public','walk','canal','1828–1848',
  'The Blackstone Canal was dug from 1825, opened on October 7, 1828 and closed in 1848. The stretch through this park was finished in 1827, its walls lined with dry-laid stone. A campaign that began in 1965 saved about three and a half miles of canal and towpath here, and the state bought the Kelly house and its farm in 1986.',
  'The canal and its towpath, which runs nearly four miles from Lonsdale north to the Kelly house. The house, once the home of the Kelly mill\'s manager, is a small transportation museum between the river and the canal.',
  '','Blackstone River State Park, 1075 Lower River Road. Grounds open dawn to dusk. DEM runs the museum, which is seasonal.',
  [W('Blackstone Canal'),['RI State Parks: Blackstone River State Park history','https://riparks.ri.gov/History-HistoryBlackstone'],['National Park Service: Kelly House Museum','https://www.nps.gov/thingstodo/kelly-house-museum-of-transportation.htm'],['National Park Service: Places to go','https://www.nps.gov/blrv/planyourvisit/placestogo.htm']]),
N('lime-rock-kilns','Lime Rock kilns','Lincoln','riprov','industry','ruins',41.92094,-71.45381,'site','ask','walk','','1600s on',
  'Lime has been quarried and burned at Lime Rock since the 17th century, and a limestone company still works there. Three colonial-era kilns survive as ruins. They were round structures of unmortared rubble stone.',
  'The pin is the second kiln, south of Sherman Avenue near Louisquisset Pike; in 1984 its walls stood 8 feet high with three openings. The first and largest, nearly 20 feet across, is near the community college west of Louisquisset Pike (about 41.89714, -71.45917). The third, one partial wall, is on the south side of Dexter Rock Road (about 41.91667, -71.42694). Their state today was not confirmed.',
  '','Ownership not checked. Ask before leaving the road.',[W('Lime Kilns (Lincoln, Rhode Island)'),W('Lime Rock, Rhode Island')],conf='mixed'),
N('scituate-reservoir-villages','Scituate Reservoir villages','Scituate','riprov','town','water',41.77247,-71.61085,'area','view','drive','drowned','1915–1926',
  'Providence took 23.1 square miles for its water supply. The reservoir flooded the villages of Ashland, Kent, South Scituate, Richmond and the west part of North Scituate, and 1,195 buildings were demolished, among them 375 homes, 7 schools and 6 mills. It began to fill on November 10, 1925.',
  'The water over the village sites. Whether any foundations show on the shore was not confirmed. The pin marks the reservoir.',
  'Five villages under Providence\'s drinking water.',
  'Run by the Providence Water Supply Board. Access rules were not confirmed. Treat the shore as closed and look from public roads.',[W('Scituate Reservoir')],conf='mixed'),
N('oakland-mill-ruins','Oakland stone mill','Burrillville','riprov','industry','ruins',41.95722,-71.64778,'area','ask','walk','','1800s',
  'The village of Oakland grew up in the 19th century around a stone mill near where the Chepachet and Clear rivers meet. The mill is now only fragments.',
  'Fragmentary stone ruins of the mill. The pin marks the village, not the ruin.',
  '','Ownership not checked.',[W('Oakland, Rhode Island')],conf='mixed'),
N('arkwright-bridge','Arkwright Bridge','Coventry','riprov','industry','standing',41.73028,-71.54694,'site','view','drive','','1888–2011',
  'An iron truss bridge built in 1888 by Dean & Westbrook to carry Hill Street over the Pawtuxet River at the Arkwright mill village. It is the longest 19th-century truss bridge left in Rhode Island. Coventry and Cranston closed it on September 30, 2011 and it has sat unused since.',
  'The single-span truss, about 128 feet long, on the Coventry and Cranston line.',
  '','Closed bridge, shut to people on foot as well. Look from the bank.',[W('Arkwright Bridge')]),
N('cranston-street-armory','Cranston Street Armory','Providence','riprov','civic','standing',41.81611,-71.42944,'site','view','drive','','1907',
  'Built in 1907 for the Rhode Island National Guard, which left in 1996. The National Trust put it on its list of most endangered historic places in 1997. A small part houses the state fire marshal and the main hall is used for storage.',
  'Yellow brick, turrets and stonework filling a city block.','','State building, mostly shut. View from the street.',[W('Cranston Street Armory')]),
N('woonsocket-rubber-mill','Woonsocket Rubber Company Mill','Woonsocket','riprov','industry','standing',42.0,-71.51722,'site','view','drive','','1865–1875',
  'Brick mill buildings put up between 1865 and 1875 by Edward Harris for one of the state\'s first rubber makers, which turned out shoes, boots and rubberized cloth. A yarn company took over in 1910. The firm\'s other mill, the Alice Mill on Fairmount Street, burned down on June 7, 2011.',
  'The three- and four-story brick ranges at 60-82 Main Street.','','View from the street.',[W('Woonsocket Rubber Company Mill')]),
N('crescent-park-carousel','Crescent Park and its Looff carousel','East Providence','riprov','amuse','standing',41.75639,-71.35917,'site','view','drive','amusements','1886–1977',
  'Crescent Park opened in 1886 on the bay at Riverside and was sold as the Coney Island of the East. It closed after the 1977 season, and most of its land is now housing. The city kept the carousel that Charles I. D. Looff built in 1895, with sixty-one horses and one camel. It still runs and is a National Historic Landmark.',
  'The carousel in its shelter building. What else of the park survives was not confirmed.',
  '','Opening season not checked.',[W('Crescent Park Looff Carousel'),W('Crescent Park (defunct amusement park)')]),
# ---- South County ----
N('fort-mansfield','Fort Mansfield','Westerly','risouth','fort','ruins',41.30639,-71.88472,'site','public','walk','forts','1901–1926',
  'A coast artillery fort on Napatree Point, on land the government bought in 1898 and first manned in 1901. War games showed it could not be defended, and it was dropped from the active list in 1909. Caretakers stayed until the land was put up for sale in 1926. The government buildings were pulled down in the winter of 1928–29.',
  'Batteries Wooster and Crawford, overgrown. A third, Battery Connell, has gone into the sea and sometimes shows at low tide. Steel covers block the steps to the lower level.',
  'A fort the sea is taking back.',
  'Listed as open to the public. Ownership not confirmed: one article gives the State of Rhode Island with the Town of Westerly in control, another says the land was sold to the Watch Hill Fire District in 1945. The lower level is blocked off; stay out of it.',[W('Fort Mansfield'),W('Napatree Point')]),
N('narragansett-towers','The Towers (Narragansett Pier Casino)','Narragansett','risouth','landmark','standing',41.43056,-71.45611,'exact','view','drive','burned','1880s–1900',
  'The only piece left of the Narragansett Pier Casino, built in the 1880s as the social centre of the resort. The casino burned on September 12, 1900, in a fire that began in the hotel next door. The loss was a blow the resort never fully got over.',
  'The Towers at 35 Ocean Road, beside the town beach. Hurricane Sandy uncovered part of the casino\'s foundation and old boardwalk; whether that still shows was not confirmed.',
  '','Public street. The building is used for events.',[W('The Towers (Narragansett, Rhode Island)'),W('Narragansett Pier Railroad')]),
N('fort-kearny','Fort Kearny','Narragansett','risouth','fort','standing',41.49056,-71.42278,'site','view','drive','forts','1901–1943',
  'A coast defense fort at Saunderstown that guarded the West Passage from 1901 to 1943, with Fort Getty and Fort Greble. Its last guns were scrapped in 1943, and it held German prisoners of war in 1945.',
  'Battery Cram and Battery Armistead, rebuilt as offices. A small research reactor stands on top of Battery French.',
  'A gun battery with a nuclear reactor on its roof.',
  'Now the University of Rhode Island\'s Narragansett Bay Campus. Working campus: view from public roads unless you have arranged a visit.',[W('Fort Kearny (Rhode Island)')]),
N('charlestown-naval-airfield','Charlestown naval airfield','Charlestown','risouth','civic','traces',41.36808,-71.66713,'site','public','walk','','1942–1974',
  'The Navy built an airfield with three runways here in 1942 as a satellite of Quonset Point. The base was closed in 1974. The hangars stood until the 1980s, and in the late 1990s the runways and taxiways were torn up and replanted with native grasses.',
  'The runway layout in the grassland. Aerial photos are said to show a bicycle track on the north ends of the runways. The March 2026 state aerial still shows wide paved strips around the pin, so some pavement survives; what it looks like on the ground was not confirmed.',
  '','Ninigret National Wildlife Refuge, with a town park on 172 acres of the old base. Refuge rules and hours were not checked.',[W('Naval Auxiliary Air Station Charlestown'),W('Ninigret National Wildlife Refuge')],conf='mixed'),
N('queens-fort-exeter','Queen\'s Fort','Exeter','risouth','fort','traces',41.59306,-71.52306,'area','ask','hike','forts','before 1676',
  'A rocky hillock long described as a Narragansett stronghold built before 1676 by Queen Quaiapen and survivors of the Great Swamp Massacre. Its walls were laid stone joining natural boulders, with a bastion on the east side.',
  'Stone walls between boulders. What can be seen today was not confirmed.',
  '','Owned by the Rhode Island Historical Society since 1931. Whether it is open to visitors was not confirmed; ask the society.',[W('Queen\'s Fort')],conf='mixed'),
N('ladd-school','Ladd School site','Exeter','risouth','inst','gone',41.5539,-71.5428,'site','view','drive','','1908–1993',
  'A state institution for people with developmental disabilities that ran from 1908 to 1993. It was modelled on the Templeton farm colony in Massachusetts. The last residents were moved out in 1993, and the final four buildings were demolished in August 2013.',
  'The buildings are gone. What is on the site now was not confirmed.',
  '','Ownership not checked. View from public roads.',[W('The Ladd School')],conf='mixed'),
N('hillsdale-mill-village','Hillsdale mill village','Richmond','risouth','town','ruins',41.52192,-71.64083,'area','ask','walk','','c.1800–1890s',
  'A mill village on the Beaver River, first called Moore\'s Mills. A grist mill went up around 1800 and a wool-carding mill in 1828. Work had stopped by the end of the 19th century.',
  'As of 1977: a few old houses, the stone ruins of the textile mill and a mill pond. Not confirmed since.',
  '','Ownership not checked.',[W('Hillsdale Historic and Archeological District')],conf='mixed'),
N('lawtons-mill','Lawton\'s Mill','Exeter','risouth','industry','standing',41.58167,-71.57028,'site','view','drive','','c.1820',
  'A wood-frame mill of about 1820 on Ten Rod Road, one of very few mill buildings of that age left in the state. An 18th-century house and a 19th-century barn stand with it.',
  'The mill, its dam and a raceway running several hundred feet north of the building.',
  '','Ownership not checked; view from the road.',[W('Lawton\'s Mill')]),
]
